  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec3 ret1, neu;
vec2 uv2,uv3;
shader_body
{
vec2 uv2;
float ang2, c, s;
uv -= 0.5;
uv *= uAspect.xy;
uv = multiply(uv, mat2(_qb));
float dist = 1;
float inten = 1;
ret1 = 0;
int anz = 2;
float n = anz;
while (n >= 0) {
ang2 = 0.0 * n/anz;
c = cos(ang2);
s = sin(ang2);
uv2.x =  uv.x*c - uv.y*s;
uv2.y =  uv.x*s + uv.y*c;
//uv2 = uv;
dist = 1.0 - fract(1.0/anz*n+q30); //evtl sqrt !
inten =  (dist)*(1.0 - dist) * 2.0;
uv3 = 3.0 * uv2*dist*(1.0 + uv.x) + vec2(q18*n,q19);
neu = texture(sampler_main,uv3) + 2.0*GetBlur1(fract(uv3)).bgr * 1.0;
ret1 = max(ret1,neu*inten);
n--;
}
//ret1 = mix(ret1,ret1.gbr,q26 / 6.0);
ret = ret1 * 2.0 + (1.0 - rad)*q26 / 3.0*GetPixel(q5 / 2.0+uv*(2.0 - rad));
}
  fragColor = vec4(ret, 1.0);
}

